import {createStudy,canvasSurface,seededRandom,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:11,title:'Gravity Room',category:'Physics / Collision',accent:'#f64b2f',background:'#eee9d7',foreground:'#182211'});
const canvas=document.querySelector('#gravity-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const colors=['#f64b2f','#dfff00','#182211','#ddd8c2','#697556','#d4d9bb'];
let bodies=[],gravity=420,drag=null,lastPointer=null;
function reset(restoreControls=false){if(restoreControls){gravity=420;document.querySelector('#gravity-force').value=420;document.querySelector('#gravity-value').textContent=420}const rand=seededRandom(511);const w=surface.width,h=surface.height;const base=Math.min(w,h);bodies=Array.from({length:28},(_,i)=>{const r=(.025+rand()*.065)*base;return{x:w*(.43+rand()*.48),y:h*(.08+rand()*.68),r:clamp(r,15,w<600?41:71),vx:(rand()-.5)*160,vy:(rand()-.5)*80,color:colors[i%colors.length],mass:r*r,spin:rand()*Math.PI*2,omega:(rand()-.5)*.4}});drag=null;lastPointer=null;canvas.style.cursor='default';document.querySelector('#gravity-status').textContent='The room is ready. Drag a sphere or fling the room.';draw();}
function draw(){const{ctx,width:w,height:h}=surface;if(!ctx)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#eee9d7';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#b4baa1';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.05,h-39);ctx.lineTo(w*.95,h-39);ctx.stroke();for(let i=0;i<bodies.length;i++){const b=bodies[i];ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.spin);ctx.fillStyle='#18221112';ctx.beginPath();ctx.ellipse(8,b.r*.7,b.r*.94,b.r*.3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(0,0,b.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle=b.color==='#182211'?'#eee9d750':'#18221188';ctx.lineWidth=.8;ctx.stroke();ctx.beginPath();ctx.ellipse(0,0,b.r*.45,b.r*.94,-.35,0,Math.PI*2);ctx.strokeStyle=b.color==='#182211'?'#eee9d738':'#18221132';ctx.stroke();ctx.fillStyle=b.color==='#182211'?'#eee9d7':'#182211';ctx.font=`${Math.max(8,b.r*.18)}px Geist, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(i+1).padStart(2,'0'),0,0);ctx.restore();}}
function tick(dt){if(dt>0){const w=surface.width,h=surface.height;for(let step=0;step<3;step++){const t=dt/3;for(const b of bodies){if(b===drag)continue;b.vy+=gravity*t;b.vx*=Math.pow(.997,t*60);b.x+=b.vx*t;b.y+=b.vy*t;b.spin+=b.omega*t;if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*.84}if(b.x>w-b.r){b.x=w-b.r;b.vx=-Math.abs(b.vx)*.84}if(b.y<b.r){b.y=b.r;b.vy=Math.abs(b.vy)*.84}if(b.y>h-b.r-40){b.y=h-b.r-40;b.vy=-Math.abs(b.vy)*.84;if(Math.abs(b.vy)<14)b.vy=0;b.vx*=.99}}for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){const a=bodies[i],b=bodies[j],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||.001,overlap=a.r+b.r-d;if(overlap<=0)continue;const nx=dx/d,ny=dy/d,invA=a===drag?0:1/a.mass,invB=b===drag?0:1/b.mass,total=invA+invB;if(!total)continue;const correction=Math.max(0,overlap-.3)/total*.72;a.x-=nx*correction*invA;a.y-=ny*correction*invA;b.x+=nx*correction*invB;b.y+=ny*correction*invB;const relative=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(relative<0){const impulse=-(1+.84)*relative/total;a.vx-=impulse*nx*invA;a.vy-=impulse*ny*invA;b.vx+=impulse*nx*invB;b.vy+=impulse*ny*invB}}}}draw();}
function point(event){const r=canvas.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top,t:event.timeStamp}}
canvas.addEventListener('pointerdown',event=>{const p=point(event);drag=[...bodies].reverse().find(b=>Math.hypot(b.x-p.x,b.y-p.y)<b.r+8)||null;if(drag){canvas.setPointerCapture(event.pointerId);lastPointer=p;drag.vx=drag.vy=0;canvas.style.cursor='grabbing'}});
canvas.addEventListener('pointermove',event=>{const p=point(event);if(drag){const elapsed=Math.max(.016,(p.t-lastPointer.t)/1000);drag.vx=clamp((p.x-lastPointer.x)/elapsed,-1600,1600);drag.vy=clamp((p.y-lastPointer.y)/elapsed,-1600,1600);drag.x=clamp(p.x,drag.r,surface.width-drag.r);drag.y=clamp(p.y,drag.r,surface.height-drag.r-40);lastPointer=p;study.invalidate()}else canvas.style.cursor=bodies.some(b=>Math.hypot(b.x-p.x,b.y-p.y)<b.r)?'grab':'default'});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>{drag=null;canvas.style.cursor='default'});
document.querySelector('#gravity-force').addEventListener('input',event=>{gravity=+event.target.value;document.querySelector('#gravity-value').textContent=gravity;study.invalidate()});
document.querySelector('#gravity-fling').addEventListener('click',()=>{const rand=seededRandom(Math.round(performance.now()));for(const b of bodies){b.vx+=(rand()-.5)*600;b.vy-=250+rand()*500;b.y=Math.max(b.r,b.y-6)}document.querySelector('#gravity-status').textContent='The room has a new direction.';study.invalidate()});
study.setReset(()=>reset(true));study.setExport(()=>downloadCanvas(canvas,'11-gravity-room.png'));study.onResize(reset);study.onFrame(({dt})=>tick(dt));study.cleanup(()=>surface.dispose());reset();
